def register():
    langs = ('fr', 'de', 'it')
    D = {l: json.load(open(ROOT / f'tools/i18n/{l}.json')) for l in langs}
    extra = json.load(open(ROOT / 'tools/i18n/extra_strings.json'))
    for row in PRESS_MORE:
        for k, l in enumerate(langs): D[l][row[2]] = row[3 + k]
    for lst in SOCIAL_MORE.values():
        for row in lst:
            for k, l in enumerate(langs): D[l][row[2]] = row[3 + k]
            if row[2] not in extra: extra.append(row[2])
    for l in langs: json.dump(D[l], open(ROOT / f'tools/i18n/{l}.json', 'w'), ensure_ascii=False, indent=0)
    json.dump(extra, open(ROOT / 'tools/i18n/extra_strings.json', 'w'), ensure_ascii=False)
    soc = {k: [[r[0], r[1], r[2]] for r in v] for k, v in SOCIAL_MORE.items()}
    js = """(function (root) {
  'use strict';
  // Generado por tools/content_press_social.py: cuentas y mensajes extra de la red social (100 %% ficticios).
  const CAA = root.CAA = root.CAA || {};
  CAA.SocialMore = { accounts: %s, templates: %s };
  if (typeof module !== 'undefined' && module.exports) module.exports = CAA.SocialMore;
})(typeof globalThis !== 'undefined' ? globalThis : this);
""" % (json.dumps(ACCOUNTS_MORE, ensure_ascii=False), json.dumps(soc, ensure_ascii=False))
    (ROOT / 'src/domain/social-more.js').write_text(js)
    print('press+', len(PRESS_MORE), 'social+', sum(len(v) for v in SOCIAL_MORE.values()))

if __name__ == '__main__': register()
